<script>function gatewayPage(){return{showTestModal:false,showGatewayModal:false,editingGateway:false,gatewayAction:'',form:{name:'',provider:'bulksmsbd',sender_id:'',api_key:'',custom_url:'',sms_api_url:'',balance_api_url:'',rate_per_part:'',is_active:false},openCreate(){this.editingGateway=false;this.gatewayAction='{{ route('owner.sms-gateways.store') }}';this.form={name:'',provider:'bulksmsbd',sender_id:'',api_key:'',custom_url:'',sms_api_url:'',balance_api_url:'',is_active:false};this.showGatewayModal=true},openEdit(g){this.editingGateway=true;this.gatewayAction=g.action;this.form={name:g.name,provider:g.provider,sender_id:g.sender_id||'',api_key:'',custom_url:g.custom_url||'',sms_api_url:g.sms_api_url||'',balance_api_url:g.balance_api_url||'',rate_per_part:g.rate_per_part||'',is_active:g.is_active};this.showGatewayModal=true}}}function confirmGatewayDelete(e,b){e.preventDefault();const f=b.closest('form');if(window.Swal){Swal.fire({title:'Delete gateway?',text:'This action cannot be undone.',icon:'warning',showCancelButton:true,confirmButtonColor:'#e11d48',confirmButtonText:'Delete'}).then(r=>{if(r.isConfirmed)f.submit()})}else if(confirm('Delete this gateway?'))f.submit()}document.addEventListener('click',function(e){const s=e.target.closest('summary');document.querySelectorAll('details').forEach(function(d){if(!s||d!==s.parentElement)d.open=false});if(s){e.preventDefault();const d=s.parentElement;d.open=true;const m=d.querySelector(':scope > div');if(m){const r=s.getBoundingClientRect();m.style.position='fixed';m.style.top=(r.bottom+2)+'px';m.style.right=Math.max(10,window.innerWidth-r.right)+'px';m.style.left='auto';m.style.zIndex='60';}}});window.addEventListener('scroll',function(){document.querySelectorAll('details[open]').forEach(function(d){d.open=false})},{passive:true});document.querySelectorAll('details').forEach(function(d){const s=[...d.querySelectorAll('span')].find(x=>x.textContent.trim()==='Active now');const del=d.querySelector('form[action*="/delete"]');if(s&&del){const f=document.createElement('form');f.method='POST';f.action=del.action.replace('/delete','/deactivate');f.innerHTML='<input type="hidden" name="_token" value="'+document.querySelector('meta[name=csrf-token]')?.content+'"><button class="w-full px-2 py-1.5 text-left text-[10px] text-amber-700 hover:bg-amber-50"><i class="fas fa-toggle-off w-4"></i>Deactivate</button>';s.replaceWith(f);}});document.querySelectorAll('details').forEach(function(d){const row=d.closest('tr'),cells=row?row.querySelectorAll('td'):[];const menu=d.querySelector(':scope > div');if(!menu||menu.querySelector('.gateway-details-btn'))return;const b=document.createElement('button');b.type='button';b.className='gateway-details-btn w-full px-2 py-1.5 text-left text-[10px] text-slate-700 hover:bg-slate-50';b.innerHTML='<i class="fas fa-circle-info w-4 text-blue-600"></i>Details';b.onclick=function(){if(window.Swal){Swal.fire({title:cells[1]?.innerText||'Gateway details',html:'<div style="text-align:left;font-size:12px;line-height:1.8"><b>Provider:</b> '+(cells[2]?.innerText||'—')+'<br><b>Sender ID:</b> '+(cells[3]?.innerText||'—')+'<br><b>Balance:</b> '+(cells[4]?.innerText||'—')+'<br><b>Per SMS:</b> '+(cells[5]?.innerText||'—')+'<br><b>Total SMS:</b> '+(cells[6]?.innerText||'—')+'<br><b>Status:</b> '+(cells[7]?.innerText||'—')+'</div>',confirmButtonText:'Close'})}d.open=false};menu.prepend(b)});</script>
<script>
document.querySelectorAll('details').forEach(function (details) {
    const menu = details.querySelector(':scope > div');
    const row = details.closest('tr');
    if (menu) {
        menu.style.width = '190px';
        menu.style.minWidth = '190px';
        menu.style.padding = '6px';
        menu.style.borderRadius = '10px';
        menu.style.boxShadow = '0 12px 30px rgba(15,23,42,.16)';
    }
    if (row && menu && row.cells[7]?.innerText.trim() === 'Active' && !menu.querySelector('.deactivate-action')) {
        const activeText = [...menu.querySelectorAll('span')].find(el => el.innerText.trim() === 'Active now');
        const deleteForm = menu.querySelector('form[action*="/delete"]');
        if (activeText && deleteForm) {
            const form = document.createElement('form');
            form.method = 'POST';
            form.action = deleteForm.action.replace('/delete', '/deactivate');
            form.className = 'deactivate-action';
            form.innerHTML = '<input type="hidden" name="_token" value="' + (document.querySelector('meta[name="csrf-token"]')?.content || '') + '"><button type="submit" class="w-full px-2 py-1.5 rounded-md text-left text-[10px] text-amber-700 hover:bg-amber-50"><i class="fas fa-toggle-off w-4"></i>Deactivate</button>';
            activeText.replaceWith(form);
        }
    }
});
</script>
